-- 023b_dev_org_chart.sql — DEV/TEST ONLY: a sample organisational structure (023).
--
-- Sorts after 023_org_chart.sql (migrate.mjs orders every file by name) and is
-- never applied in staging or production (migrations/dev/). Hand-maintained,
-- not generated by tools/seed-from-prototype.mjs.
--
-- Generic structure titles only — no invented people. The three linked
-- holders are the board/executive members 002_seed.sql already inserts.
-- Covers what the dashboard and the public page need to show: four levels
-- (auto tones by depth), holders under a box, a box with holders hidden, and
-- one unpublished position (absent from GET /org-chart, shown as hidden in
-- the dashboard). Every position stays editable from the dashboard.

INSERT INTO org_positions (name_ar, name_en, parent_id, show_holders, is_published, sort_order)
  VALUES ('الجمعية العمومية', 'General assembly', NULL, 1, 1, 1);
SET @dev_assembly = LAST_INSERT_ID();

INSERT INTO org_positions (name_ar, name_en, parent_id, show_holders, is_published, sort_order)
  VALUES ('مجلس الإدارة', 'Board of directors', @dev_assembly, 1, 1, 1);
SET @dev_board = LAST_INSERT_ID();

INSERT INTO org_positions (name_ar, name_en, parent_id, show_holders, is_published, sort_order)
  VALUES ('رئيس مجلس الإدارة', 'Chair of the board', @dev_board, 1, 1, 1);
SET @dev_chair = LAST_INSERT_ID();
INSERT INTO org_positions (name_ar, name_en, parent_id, show_holders, is_published, sort_order)
  VALUES ('نائب رئيس مجلس الإدارة', 'Vice chair', @dev_board, 1, 1, 2);
SET @dev_vice = LAST_INSERT_ID();
INSERT INTO org_positions (name_ar, name_en, parent_id, show_holders, is_published, sort_order)
  VALUES ('لجنة المراجعة', 'Audit committee', @dev_board, 0, 1, 3);
INSERT INTO org_positions (name_ar, name_en, parent_id, show_holders, is_published, sort_order)
  VALUES ('المدير التنفيذي', 'Executive director', @dev_board, 1, 1, 4);
SET @dev_exec = LAST_INSERT_ID();

INSERT INTO org_positions (name_ar, name_en, parent_id, show_holders, is_published, sort_order) VALUES
  ('الشؤون المالية والإدارية', 'Finance and administration', @dev_exec, 1, 1, 1),
  ('إدارة البرامج', 'Programmes', @dev_exec, 1, 1, 2),
  ('العلاقات العامة والإعلام', 'Public relations and media', @dev_exec, 1, 1, 3),
  ('وحدة الجودة', 'Quality unit', @dev_exec, 1, 0, 4);

UPDATE board_members SET org_position_id = @dev_chair WHERE grp = 'board' AND role_en = 'Chairman';
UPDATE board_members SET org_position_id = @dev_vice WHERE grp = 'board' AND role_en = 'Vice Chairman';
UPDATE board_members SET org_position_id = @dev_exec WHERE grp = 'executive' AND role_en = 'Executive Director';
